func NewSavedItemClient(c config) *SavedItemClient {
	return &SavedItemClient{config: c}
}

// Use adds a list of mutation hooks to the hooks stack.
// A call to `Use(f, g, h)` equals to `saveditem.Hooks(f(g(h())))`.
func (c *SavedItemClient) Use(hooks ...Hook) {
	c.hooks.SavedItem = append(c.hooks.SavedItem, hooks...)
}

// Intercept adds a list of query interceptors to the interceptors stack.
// A call to `Intercept(f, g, h)` equals to `saveditem.Intercept(f(g(h())))`.
func (c *SavedItemClient) Intercept(interceptors ...Interceptor) {
	c.inters.SavedItem = append(c.inters.SavedItem, interceptors...)
}

// Create returns a builder for creating a SavedItem entity.
func (c *SavedItemClient) Create() *SavedItemCreate {
	mutation := newSavedItemMutation(c.config, OpCreate)
	return &SavedItemCreate{config: c.config, hooks: c.Hooks(), mutation: mutation}
}

// CreateBulk returns a builder for creating a bulk of SavedItem entities.
func (c *SavedItemClient) CreateBulk(builders ...*SavedItemCreate) *SavedItemCreateBulk {
	return &SavedItemCreateBulk{config: c.config, builders: builders}
}

// MapCreateBulk creates a bulk creation builder from the given slice. For each item in the slice, the function creates
// a builder and applies setFunc on it.
func (c *SavedItemClient) MapCreateBulk(slice any, setFunc func(*SavedItemCreate, int)) *SavedItemCreateBulk {
	rv := reflect.ValueOf(slice)
	if rv.Kind() != reflect.Slice {
		return &SavedItemCreateBulk{err: fmt.Errorf("calling to SavedItemClient.MapCreateBulk with wrong type %T, need slice", slice)}
	}
	builders := make([]*SavedItemCreate, rv.Len())
	for i := 0; i < rv.Len(); i++ {
		builders[i] = c.Create()
		setFunc(builders[i], i)
	}
	return &SavedItemCreateBulk{config: c.config, builders: builders}
}

// Update returns an update builder for SavedItem.
func (c *SavedItemClient) Update() *SavedItemUpdate {
	mutation := newSavedItemMutation(c.config, OpUpdate)
	return &SavedItemUpdate{config: c.config, hooks: c.Hooks(), mutation: mutation}
}

// UpdateOne returns an update builder for the given entity.
func (c *SavedItemClient) UpdateOne(_m *SavedItem) *SavedItemUpdateOne {
	mutation := newSavedItemMutation(c.config, OpUpdateOne, withSavedItem(_m))
	return &SavedItemUpdateOne{config: c.config, hooks: c.Hooks(), mutation: mutation}
}

// UpdateOneID returns an update builder for the given id.
func (c *SavedItemClient) UpdateOneID(id int) *SavedItemUpdateOne {
	mutation := newSavedItemMutation(c.config, OpUpdateOne, withSavedItemID(id))
	return &SavedItemUpdateOne{config: c.config, hooks: c.Hooks(), mutation: mutation}
}

// Delete returns a delete builder for SavedItem.
func (c *SavedItemClient) Delete() *SavedItemDelete {
	mutation := newSavedItemMutation(c.config, OpDelete)
	return &SavedItemDelete{config: c.config, hooks: c.Hooks(), mutation: mutation}
}

// DeleteOne returns a builder for deleting the given entity.
func (c *SavedItemClient) DeleteOne(_m *SavedItem) *SavedItemDeleteOne {
	return c.DeleteOneID(_m.ID)
}

// DeleteOneID returns a builder for deleting the given entity by its id.
func (c *SavedItemClient) DeleteOneID(id int) *SavedItemDeleteOne {
	builder := c.Delete().Where(saveditem.ID(id))
	builder.mutation.id = &id
	builder.mutation.op = OpDeleteOne
	return &SavedItemDeleteOne{builder}
}

// Query returns a query builder for SavedItem.
func (c *SavedItemClient) Query() *SavedItemQuery {
	return &SavedItemQuery{
		config: c.config,
		ctx:    &QueryContext{Type: TypeSavedItem},
		inters: c.Interceptors(),
	}
}

// Get returns a SavedItem entity by its id.
func (c *SavedItemClient) Get(ctx context.Context, id int) (*SavedItem, error) {
	return c.Query().Where(saveditem.ID(id)).Only(ctx)
}

// GetX is like Get, but panics if an error occurs.
func (c *SavedItemClient) GetX(ctx context.Context, id int) *SavedItem {
	obj, err := c.Get(ctx, id)
	if err != nil {
		panic(err)
	}
	return obj
}

// Hooks returns the client hooks.
func (c *SavedItemClient) Hooks() []Hook {
	return c.hooks.SavedItem
}

// Interceptors returns the client interceptors.
func (c *SavedItemClient) Interceptors() []Interceptor {
	return c.inters.SavedItem
}

func (c *SavedItemClient) mutate(ctx context.Context, m *SavedItemMutation) (Value, error) {
	switch m.Op() {
	case OpCreate:
		return (&SavedItemCreate{config: c.config, hooks: c.Hooks(), mutation: m}).Save(ctx)
	case OpUpdate:
		return (&SavedItemUpdate{config: c.config, hooks: c.Hooks(), mutation: m}).Save(ctx)
	case OpUpdateOne:
		return (&SavedItemUpdateOne{config: c.config, hooks: c.Hooks(), mutation: m}).Save(ctx)
	case OpDelete, OpDeleteOne:
		return (&SavedItemDelete{config: c.config, hooks: c.Hooks(), mutation: m}).Exec(ctx)
	default:
		return nil, fmt.Errorf("ent: unknown SavedItem mutation op: %q", m.Op())
	}
}

// hooks and interceptors per client, for fast access.
type (
	hooks struct {
		Connection, Conversation, ImportRun, Invitation, Message, Person, RawRecord,
		SavedItem []ent.Hook
	}
	inters struct {
		Connection, Conversation, ImportRun, Invitation, Message, Person, RawRecord,
		SavedItem []ent.Interceptor
	}
)
